-- KL Electricals — schema
--
-- GENERATED by scripts/rebuild-schema.js from a migrated database. Do not edit
-- the CREATE TABLE statements by hand — add a migration, apply it, and run
--   npm run migrate && npm run rebuild-schema && npm run build-init-sql
-- The prose above each table IS hand-written and is carried across on every
-- regeneration, so it is the right place to explain a table.
--
-- No default users and no application data. The one exception is the reference
-- rows at the foot of the file — the shift timings and the cash-discount
-- ladder — which the code reads by key and cannot work without.
--
-- Tables are ordered so every foreign-key target exists before its referrer,
-- apart from one deliberate cycle handled by an ALTER at the end.
--
-- Conventions applied consistently across every table:
--   money     DECIMAL(15,2)
--   quantity  DECIMAL(15,4)
--   percent   DECIMAL(5,2)
--   latitude  DECIMAL(10,8)   -- +/-90,  8 fractional digits (~1.1mm)
--   longitude DECIMAL(11,8)   -- +/-180, 8 fractional digits
--
-- Every point-in-time column is DATETIME, never TIMESTAMP. TIMESTAMP overflows
-- in 2038 and is silently rewritten between the session time zone and UTC on
-- every read and write -- the exact conversion config/db.js pins to UTC to
-- avoid. DATETIME stores the literal value and is not converted, so the two
-- mechanisms cannot disagree.

-- ---------------------------------------------------------------------------
-- alert_log
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS alert_log (
  id int NOT NULL AUTO_INCREMENT,
  kind varchar(40) NOT NULL,
  ref_type varchar(24) NOT NULL DEFAULT '',
  ref_id varchar(40) NOT NULL DEFAULT '',
  on_date date NOT NULL,
  detail varchar(255) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_alert (kind,ref_type,ref_id,on_date),
  KEY idx_date (on_date,kind)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- cash_discount_bands
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cash_discount_bands (
  id int NOT NULL AUTO_INCREMENT,
  label varchar(40) NOT NULL,
  min_days int NOT NULL,
  max_days int NOT NULL,
  percent decimal(6,4) NOT NULL,
  is_active tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (id),
  KEY idx_days (min_days,max_days)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- incentive_segments
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS incentive_segments (
