  PRIMARY KEY (id),
  UNIQUE KEY unique_segment_name (name),
  CONSTRAINT incentive_segments_chk_1 CHECK (json_valid(match_brands))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

