-- ---------------------------------------------------------------------------
-- users
-- `permissions` is a JSON array matched by userCan(): ["all"] | ["items"] | ["items.create"]
-- No temp_password column: a recoverable password beside a bcrypt hash defeats the hash.
-- email is UNIQUE so a duplicate is rejected by the database rather than by a
-- check-then-insert in application code, which cannot be made race-free.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id varchar(20) NOT NULL,
  name varchar(100) NOT NULL,
  email varchar(100) DEFAULT NULL,
  phone varchar(20) DEFAULT NULL,
  role enum('admin','employee') NOT NULL DEFAULT 'employee',
  shift_code varchar(8) DEFAULT NULL,
  fixed_salary decimal(15,2) NOT NULL DEFAULT '0.00',
  geofenced tinyint(1) NOT NULL DEFAULT '1',
  password varchar(255) NOT NULL,
  must_change_password tinyint(1) NOT NULL DEFAULT '0',
  password_changed_at datetime DEFAULT NULL,
  permissions longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  address text,
  city varchar(50) DEFAULT NULL,
  state varchar(50) DEFAULT NULL,
  is_active tinyint(1) DEFAULT '1',
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_email (email),
  KEY created_by (created_by),
  KEY fk_user_shift (shift_code),
  CONSTRAINT fk_user_shift FOREIGN KEY (shift_code) REFERENCES shifts (code) ON DELETE SET NULL,
  CONSTRAINT users_ibfk_1 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT users_chk_1 CHECK (json_valid(permissions))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- holidays — non-working days removed from the attendance calculation so they
-- do not count as absences.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS holidays (
  id int NOT NULL AUTO_INCREMENT,
  holiday_date date NOT NULL,
  name varchar(150) NOT NULL,
  is_custom tinyint(1) DEFAULT '0',
  is_active tinyint(1) DEFAULT '1',
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY holiday_date (holiday_date),
  KEY idx_year (holiday_date),
  KEY created_by (created_by),
  CONSTRAINT holidays_ibfk_1 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- location_logs — background GPS pings (10-minute interval) plus check-in/out
-- fixes. Live tracking reads the latest row per user; history reads a day's trail.
--
-- This table is the only one that grows without a natural ceiling: roughly 50
-- rows per employee per working day. scripts/purge-locations.js deletes rows
-- older than LOCATION_RETENTION_DAYS and is meant to run on a schedule.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS location_logs (
  id int NOT NULL AUTO_INCREMENT,
  user_id varchar(20) NOT NULL,
  latitude decimal(10,8) NOT NULL,
  longitude decimal(11,8) NOT NULL,
  recorded_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_user_date (user_id,recorded_at),
  KEY idx_recorded_at (recorded_at),
  CONSTRAINT location_logs_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- items
-- masterid is AUTO_INCREMENT here. In the source project it was a Tally-owned
-- ID, and manually created items were given negative IDs via a MIN() scan on
-- every insert. With no Tally integration that scheme has no purpose and races
-- under concurrent inserts, so the database issues IDs instead.
--
-- qty is a CACHED current stock level, not the source of truth. It equals
-- SUM(stock_movements.change_qty) for the item and is maintained inside the
-- same transaction as the movement row. Recompute it at any time with:
--   UPDATE items i SET qty = COALESCE(
--     (SELECT SUM(m.change_qty) FROM stock_movements m WHERE m.item_id = i.masterid), 0);
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS items (
  masterid int NOT NULL AUTO_INCREMENT,
  name varchar(100) NOT NULL,
  code varchar(50) DEFAULT NULL,
  brand varchar(100) DEFAULT NULL,
  category varchar(100) DEFAULT NULL,
  hsn varchar(20) DEFAULT NULL,
  gst_percent decimal(5,2) DEFAULT '0.00',
  unit varchar(30) DEFAULT NULL,
  pricing_type enum('list_less_disc','net') DEFAULT NULL,
  base_price decimal(15,2) NOT NULL DEFAULT '0.00',
  disc_dealer decimal(6,4) DEFAULT NULL,
  disc_builder_direct decimal(6,4) DEFAULT NULL,
  disc_builder_comm decimal(6,4) DEFAULT NULL,
  disc_retail_direct decimal(6,4) DEFAULT NULL,
  disc_retail_comm decimal(6,4) DEFAULT NULL,
  disc_electrician decimal(6,4) DEFAULT NULL,
  ratio_builder_direct decimal(8,6) DEFAULT NULL,
  ratio_builder_comm decimal(8,6) DEFAULT NULL,
  ratio_retail_direct decimal(8,6) DEFAULT NULL,
  ratio_retail_comm decimal(8,6) DEFAULT NULL,
  ratio_electrician decimal(8,6) DEFAULT NULL,
  comm_retail_agent decimal(6,4) DEFAULT NULL,
  comm_builder_agent decimal(6,4) DEFAULT NULL,
  scheme_weightage decimal(6,4) DEFAULT NULL,
  sch_modular_monthly tinyint(1) DEFAULT NULL,
  sch_modular_quarterly tinyint(1) DEFAULT NULL,
  sch_modular_yearly tinyint(1) DEFAULT NULL,
  sch_dream_monthly tinyint(1) DEFAULT NULL,
  sch_boxes_monthly tinyint(1) DEFAULT NULL,
  sch_electrician tinyint(1) DEFAULT NULL,
  sch_cash_discount tinyint(1) DEFAULT NULL,
  modular_weightage decimal(6,4) DEFAULT NULL,
  incentive_category varchar(30) DEFAULT NULL,
  incentive_segment_id int DEFAULT NULL,
  cost_price decimal(15,2) DEFAULT NULL,
  return_penalty_percent decimal(6,4) DEFAULT NULL,
  tally_last_purchase_rate decimal(15,2) DEFAULT NULL,
  tally_last_purchase_on date DEFAULT NULL,
  min_stock decimal(15,4) NOT NULL DEFAULT '0.0000',
  godown varchar(40) DEFAULT NULL,
  rack varchar(40) DEFAULT NULL,
  rate decimal(15,2) NOT NULL DEFAULT '0.00',
  discount decimal(5,2) DEFAULT '0.00',
  qty decimal(15,4) NOT NULL DEFAULT '0.0000',
  is_active tinyint(1) DEFAULT '1',
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (masterid),
  KEY idx_name (name),
  KEY idx_active (is_active),
  KEY idx_brand (brand),
  KEY idx_priced (pricing_type,is_active),
  KEY idx_incentive_cat (incentive_category),
  KEY idx_incentive_segment (incentive_segment_id),
  CONSTRAINT fk_item_segment FOREIGN KEY (incentive_segment_id) REFERENCES incentive_segments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- stock_movements — the ledger that makes items.qty recomputable.
--
-- change_qty is SIGNED: negative removes stock (an order), positive adds it (a
-- goods receipt or a customer return). Nothing here is ever updated or deleted;
-- a mistake is corrected by writing an opposing 'adjustment' row, so the trail
-- always reconstructs how a level was reached.
--
-- ref_type/ref_id point loosely at whatever caused the movement ('order' with
-- the order_id, for example). It is deliberately not a foreign key: an
-- adjustment or an opening balance has no referent, and cancelling an order
-- must not erase the movement history that order produced.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_movements (
  id int NOT NULL AUTO_INCREMENT,
  item_id int NOT NULL,
  change_qty decimal(15,4) NOT NULL,
  reason enum('order','receipt','adjustment','return','opening','transfer') NOT NULL,
  ref_type varchar(20) DEFAULT NULL,
  ref_id int DEFAULT NULL,
  note varchar(255) DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_item (item_id,created_at),
  KEY idx_ref (ref_type,ref_id),
  KEY created_by (created_by),
  CONSTRAINT stock_movements_ibfk_1 FOREIGN KEY (item_id) REFERENCES items (masterid),
  CONSTRAINT stock_movements_ibfk_2 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- customers
-- masterid is AUTO_INCREMENT for the same reason as items.
-- No beat_id: beats are out of scope. group_name carries customer grouping.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
  masterid int NOT NULL AUTO_INCREMENT,
  name varchar(100) NOT NULL,
  group_name varchar(100) DEFAULT NULL,
  person_name varchar(100) DEFAULT NULL,
  phone varchar(20) DEFAULT NULL,
  phone2 varchar(20) DEFAULT NULL,
  email varchar(100) DEFAULT NULL,
  address text,
  pincode varchar(10) DEFAULT NULL,
  state varchar(100) DEFAULT NULL,
  city varchar(50) DEFAULT NULL,
  gst_number varchar(20) DEFAULT NULL,
  pan_number varchar(20) DEFAULT NULL,
  closing_balance decimal(15,2) DEFAULT '0.00',
  latitude decimal(10,8) DEFAULT NULL,
  longitude decimal(11,8) DEFAULT NULL,
  category varchar(50) DEFAULT NULL,
  customer_type enum('dealer','retail_direct','retail_commission','electrician_direct','builder_direct','builder_commission') DEFAULT NULL,
  salesman_id varchar(20) DEFAULT NULL,
  birth_date date DEFAULT NULL,
  anniversary date DEFAULT NULL,
  credit_limit decimal(15,2) DEFAULT '0.00',
  credit_days int NOT NULL DEFAULT '0',
  is_active tinyint(1) DEFAULT '1',
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (masterid),
  KEY idx_name (name),
  KEY idx_active (is_active),
  KEY idx_type (customer_type),
  KEY idx_salesman (salesman_id),
  CONSTRAINT fk_customer_salesman FOREIGN KEY (salesman_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Commission agents
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- agents -- builders, electricians and interior designers who introduce a sale.
--
-- phone is UNIQUE and is the lookup key: a name is spelled six ways across a
-- ledger and a phone number is not. Uniqueness is enforced here rather than by a
-- SELECT-then-INSERT, which cannot be made race-free.
--
-- agent_type selects the commission rate column (21 for builders, 20 for
-- electricians and interior), which is why it is NOT NULL -- a ledger created
-- without it owes an amount nobody can compute.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agents (
  id int NOT NULL AUTO_INCREMENT,
  name varchar(100) NOT NULL,
  phone varchar(20) NOT NULL,
  phone2 varchar(20) DEFAULT NULL,
  agent_type enum('builder','electrician') NOT NULL,
  area varchar(100) DEFAULT NULL,
  notes varchar(255) DEFAULT NULL,
  profession varchar(50) DEFAULT NULL,
  is_active tinyint(1) DEFAULT '1',
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_phone (phone),
  KEY idx_name (name),
  KEY idx_active (is_active),
  KEY created_by (created_by),
  CONSTRAINT agents_ibfk_1 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- beat_plans / beat_stops -- the salesman's planned round for a day.
--
-- The service day comes from utils/businessDay.js, not from a UTC date: a plan
-- filed at 05:15 IST belongs to today, and toISOString().slice(0,10) would file
-- it under yesterday.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS beat_plans (
  id int NOT NULL AUTO_INCREMENT,
  employee_id varchar(20) NOT NULL,
  plan_date date NOT NULL,
  beat_name varchar(150) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_employee_day (employee_id,plan_date),
  CONSTRAINT beat_plans_ibfk_1 FOREIGN KEY (employee_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Schemes
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- schemes / scheme_slabs / scheme_ledger -- electrician incentives.
--
-- As with agent commission, the reward is recorded against the electrician and
-- never printed on the party's invoice. scheme_ledger is append-only for the
-- same reason: what someone earned in June must not change in July.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS schemes (
  id int NOT NULL AUTO_INCREMENT,
  name varchar(150) NOT NULL,
  kind enum('electrician_gift','growth_credit','growth_gift') NOT NULL DEFAULT 'electrician_gift',
  period enum('once','monthly','quarterly','yearly') NOT NULL DEFAULT 'once',
  renews tinyint(1) NOT NULL DEFAULT '0',
  requires_payment tinyint(1) NOT NULL DEFAULT '1',
  item_flag varchar(30) DEFAULT NULL,
  early_bird_days int NOT NULL DEFAULT '30',
  referral_bonus decimal(15,2) NOT NULL DEFAULT '0.00',
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  is_active tinyint(1) DEFAULT '1',
  note varchar(255) DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_window (starts_on,ends_on),
  KEY created_by (created_by),
  KEY idx_kind_active (kind,is_active),
  CONSTRAINT schemes_ibfk_1 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- scheme_slabs
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS scheme_slabs (
  id int NOT NULL AUTO_INCREMENT,
  scheme_id int NOT NULL,
  slab_order int NOT NULL DEFAULT '0',
  min_qty decimal(15,4) NOT NULL,
  max_qty decimal(15,4) DEFAULT NULL,
  min_value decimal(15,2) DEFAULT NULL,
  reward_rate decimal(15,2) NOT NULL,
  reward_percent decimal(6,4) DEFAULT NULL,
  reward_gift varchar(120) DEFAULT NULL,
  reward_note varchar(150) DEFAULT NULL,
  PRIMARY KEY (id),
  KEY idx_scheme (scheme_id,min_qty),
  KEY idx_scheme_value (scheme_id,min_value),
  CONSTRAINT scheme_slabs_ibfk_1 FOREIGN KEY (scheme_id) REFERENCES schemes (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- eod_closings -- one row per closed service day.
--
-- counted_cash is what was physically in the drawer; expected_cash is what the
-- ledger says. The variance is stored rather than recomputed, because the
-- figures behind it keep moving and the variance is a statement about a moment.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS eod_closings (
  id int NOT NULL AUTO_INCREMENT,
  close_date date NOT NULL,
  opening_cash decimal(15,2) NOT NULL DEFAULT '0.00',
  cash_in decimal(15,2) NOT NULL DEFAULT '0.00',
  cheques_in decimal(15,2) NOT NULL DEFAULT '0.00',
  upi_in decimal(15,2) NOT NULL DEFAULT '0.00',
  expenses decimal(15,2) NOT NULL DEFAULT '0.00',
  expected_cash decimal(15,2) NOT NULL DEFAULT '0.00',
  counted_cash decimal(15,2) NOT NULL DEFAULT '0.00',
  variance decimal(15,2) NOT NULL DEFAULT '0.00',
  note varchar(255) DEFAULT NULL,
  closed_by varchar(20) DEFAULT NULL,
  closed_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_day (close_date),
  KEY closed_by (closed_by),
  CONSTRAINT eod_closings_ibfk_1 FOREIGN KEY (closed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Stock count
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- stock_counts / stock_count_lines -- physical reconciliation.
--
-- Posting a count writes one `adjustment` movement per varied line and
-- recomputes the cached quantity. Nothing is edited: the count that found the
-- loss and the loss itself both stay in the ledger.
--
-- system_qty is snapshotted when the line is counted, so the variance recorded
-- is the one the counter actually saw, not one recomputed after later sales.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_counts (
  id int NOT NULL AUTO_INCREMENT,
  godown varchar(120) DEFAULT NULL,
  count_date date NOT NULL,
  assigned_to varchar(20) DEFAULT NULL,
  is_auto tinyint(1) NOT NULL DEFAULT '0',
  status enum('open','posted') NOT NULL DEFAULT 'open',
  started_by varchar(20) DEFAULT NULL,
  started_at datetime DEFAULT CURRENT_TIMESTAMP,
  posted_at datetime DEFAULT NULL,
  PRIMARY KEY (id),
  KEY idx_date (count_date),
  KEY started_by (started_by),
  KEY fk_count_assignee (assigned_to),
  CONSTRAINT fk_count_assignee FOREIGN KEY (assigned_to) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT stock_counts_ibfk_1 FOREIGN KEY (started_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- stock_count_lines
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_count_lines (
  id int NOT NULL AUTO_INCREMENT,
  count_id int NOT NULL,
  item_id int NOT NULL,
  item_name varchar(100) NOT NULL,
  rack varchar(30) DEFAULT NULL,
  system_qty decimal(15,4) NOT NULL,
  counted_qty decimal(15,4) DEFAULT NULL,
  variance decimal(15,4) DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY unique_count_item (count_id,item_id),
  KEY idx_count (count_id),
  KEY item_id (item_id),
  CONSTRAINT stock_count_lines_ibfk_1 FOREIGN KEY (count_id) REFERENCES stock_counts (id) ON DELETE CASCADE,
  CONSTRAINT stock_count_lines_ibfk_2 FOREIGN KEY (item_id) REFERENCES items (masterid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Notifications
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- notifications -- what the business was told, and when.
--
-- user_id NULL means the alert is for everyone who can see it (a broadcast);
-- a value targets one person, which is how a verify mismatch reaches Yash.
--
-- Read state is a column rather than a delete: these rows are the audit trail of
-- what was raised, and a dismiss that loses that is worse than a long list.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS notifications (
  id int NOT NULL AUTO_INCREMENT,
  user_id varchar(20) DEFAULT NULL,
  tone enum('info','success','warning','danger') NOT NULL DEFAULT 'info',
  title varchar(150) NOT NULL,
  body varchar(500) DEFAULT NULL,
  actor varchar(60) DEFAULT NULL,
  ref_type varchar(20) DEFAULT NULL,
  ref_id int DEFAULT NULL,
  is_read tinyint(1) NOT NULL DEFAULT '0',
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_user_read (user_id,is_read,created_at),
  KEY idx_created (created_at),
  CONSTRAINT notifications_ibfk_1 FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- attachments -- files captured in the field.
--
-- A delivery photo is the proof of delivery (R06), so the file has to live
-- somewhere the row can point at. Stored on the API host's disk under
-- backend/uploads and served through an authenticated route -- these are
-- photographs of identified people's premises, and a public static mount would
-- make the whole delivery history readable to anyone who guessed a filename.
--
-- The row records who uploaded what and against which document; `stored_name`
-- is the on-disk name, which is generated and never the client's own filename.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS attachments (
  id int NOT NULL AUTO_INCREMENT,
  stored_name varchar(120) NOT NULL,
  original_name varchar(255) DEFAULT NULL,
  mime_type varchar(60) DEFAULT NULL,
  byte_size int DEFAULT NULL,
  ref_type varchar(20) DEFAULT NULL,
  ref_id int DEFAULT NULL,
