) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- orders
-- No sync_status / tally_* columns: the Tally sync workflow is out of scope.
-- No client_ref: the offline order queue is not in v1. Adding it later is one
--   ALTER TABLE orders ADD COLUMN client_ref VARCHAR(64) NULL,
--   ADD UNIQUE KEY unique_client_ref (client_ref);
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS orders (
  order_id int NOT NULL AUTO_INCREMENT,
  so_number varchar(24) DEFAULT NULL,
  customer_id int NOT NULL,
  customer_type varchar(24) DEFAULT NULL,
  order_date date NOT NULL,
  total_amount decimal(15,2) DEFAULT '0.00',
  created_by varchar(20) DEFAULT NULL,
  salesman_id varchar(20) DEFAULT NULL,
  agent_id int DEFAULT NULL,
  agent_commission decimal(15,2) NOT NULL DEFAULT '0.00',
  scheme_member_id int DEFAULT NULL,
  scheme_qualifying decimal(15,2) NOT NULL DEFAULT '0.00',
  status enum('pending','confirmed','completed','cancelled','approved','rejected','picking','picked','verified','invoiced','dispatched','delivered','undelivered') DEFAULT 'pending',
  is_no_order tinyint(1) NOT NULL DEFAULT '0',
  notes text,
  delivered_to varchar(100) DEFAULT NULL,
  delivery_mode enum('kl_auto','bhaara_auto','kl_scooty','rapido') DEFAULT NULL,
  urgency enum('hours','days') DEFAULT NULL,
  special_instructions text,
  payment_mode enum('cash','upi','credit','pdc','split') DEFAULT NULL,
  gps_lat decimal(10,8) DEFAULT NULL,
  gps_lng decimal(11,8) DEFAULT NULL,
  gps_place varchar(160) DEFAULT NULL,
  gps_place_source enum('client','geocoded','manual') DEFAULT NULL,
  approved_by varchar(20) DEFAULT NULL,
  approved_at datetime DEFAULT NULL,
  verified_by varchar(20) DEFAULT NULL,
  verified_at datetime DEFAULT NULL,
  verify_sign_id int DEFAULT NULL,
  reject_reason varchar(255) DEFAULT NULL,
  duplicate_ack tinyint(1) NOT NULL DEFAULT '0',
  order_photo_id int DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (order_id),
  UNIQUE KEY unique_so_number (so_number),
  KEY idx_order_date (order_date),
  KEY idx_created_by (created_by),
  KEY idx_no_order (is_no_order),
  KEY customer_id (customer_id),
  KEY idx_agent (agent_id),
  KEY idx_salesman_order (salesman_id,order_date),
  KEY fk_order_approver (approved_by),
  KEY fk_order_verifier (verified_by),
  KEY fk_order_sign (verify_sign_id),
  KEY fk_order_photo (order_photo_id),
  CONSTRAINT fk_order_agent FOREIGN KEY (agent_id) REFERENCES agents (id) ON DELETE SET NULL,
  CONSTRAINT fk_order_approver FOREIGN KEY (approved_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_order_photo FOREIGN KEY (order_photo_id) REFERENCES attachments (id) ON DELETE SET NULL,
  CONSTRAINT fk_order_salesman FOREIGN KEY (salesman_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_order_sign FOREIGN KEY (verify_sign_id) REFERENCES attachments (id) ON DELETE SET NULL,
  CONSTRAINT fk_order_verifier FOREIGN KEY (verified_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT orders_ibfk_1 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT orders_ibfk_2 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- order_items
-- item_name, hsn, rate and gst_percent are snapshotted at write time, so later
-- edits to the item master never rewrite order history.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_items (
  id int NOT NULL AUTO_INCREMENT,
  order_id int NOT NULL,
  item_id int NOT NULL,
  item_name varchar(100) NOT NULL,
  hsn varchar(20) DEFAULT NULL,
  qty decimal(15,4) NOT NULL,
  rate decimal(15,2) NOT NULL,
  pricing_type varchar(20) DEFAULT NULL,
  base_price decimal(15,2) DEFAULT NULL,
  price_factor decimal(8,6) DEFAULT NULL,
  previous_rate decimal(15,2) DEFAULT NULL,
  cost_price decimal(15,2) DEFAULT NULL,
  below_cost tinyint(1) NOT NULL DEFAULT '0',
  commission_pct decimal(6,4) DEFAULT NULL,
  commission_amt decimal(15,2) NOT NULL DEFAULT '0.00',
  scheme_weightage decimal(6,4) DEFAULT NULL,
  scheme_value decimal(15,2) NOT NULL DEFAULT '0.00',
  scheme decimal(5,2) DEFAULT '0.00',
  discount decimal(5,2) DEFAULT '0.00',
  gst_percent decimal(5,2) DEFAULT '0.00',
  gst_amount decimal(15,2) DEFAULT '0.00',
  total decimal(15,2) NOT NULL,
  PRIMARY KEY (id),
  KEY order_id (order_id),
  KEY item_id (item_id),
  CONSTRAINT order_items_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT order_items_ibfk_2 FOREIGN KEY (item_id) REFERENCES items (masterid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Order workflow
--
-- Added for the phone app (July 2026 screens). The pipeline is a state machine
-- on orders.status; everything below records how an order moved and what was
-- physically found at each stage.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- order_events -- append-only trail of status transitions.
--
-- Same principle as stock_movements: the current stage lives on orders.status
-- for cheap filtering, and this table is why that column can be trusted. Nothing
-- here is ever updated or deleted, so "who approved SO-147, and when" survives
-- the order being cancelled and reinstated twice.
--
-- from_status is nullable because the first event of an order's life has no
-- predecessor.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_events (
  id int NOT NULL AUTO_INCREMENT,
  order_id int NOT NULL,
  from_status varchar(20) DEFAULT NULL,
  to_status varchar(20) NOT NULL,
  note varchar(255) DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_order (order_id,created_at),
  KEY created_by (created_by),
  CONSTRAINT order_events_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT order_events_ibfk_2 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- order_picks -- what the picker actually found, per order line.
--
-- One row per order_item, created when picking starts. picked_qty is what came
-- off the rack; `status` is derived from it by the route and stored so the sheet
-- can be filtered without recomputing. A short pick is NOT an error here -- it is
-- the fact the verify step and Yash's alert both depend on.
--
-- UNIQUE on order_item_id: a line is picked once. Re-picking updates the row,
-- which is safe because the pick is a working note, not a ledger -- the ledger
-- entry is the stock movement the order already wrote.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_picks (
  id int NOT NULL AUTO_INCREMENT,
  order_id int NOT NULL,
  order_item_id int NOT NULL,
  rack varchar(30) DEFAULT NULL,
  need_qty decimal(15,4) NOT NULL,
  picked_qty decimal(15,4) NOT NULL DEFAULT '0.0000',
  status enum('pending','done','partial','missing') NOT NULL DEFAULT 'pending',
  note varchar(255) DEFAULT NULL,
  photo_id int DEFAULT NULL,
  picked_by varchar(20) DEFAULT NULL,
  picked_at datetime DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY unique_line (order_item_id),
  KEY idx_order (order_id),
  KEY picked_by (picked_by),
  KEY fk_pick_photo (photo_id),
  CONSTRAINT fk_pick_photo FOREIGN KEY (photo_id) REFERENCES attachments (id) ON DELETE SET NULL,
  CONSTRAINT order_picks_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT order_picks_ibfk_2 FOREIGN KEY (order_item_id) REFERENCES order_items (id) ON DELETE CASCADE,
  CONSTRAINT order_picks_ibfk_3 FOREIGN KEY (picked_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- order_verifications -- Ajit's physical count before billing (R02).
--
-- expected_qty is snapshotted rather than joined back to order_items, because a
-- verification is evidence about a moment: if the order is later modified, the
-- count must still say what was expected when it was taken.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_verifications (
  id int NOT NULL AUTO_INCREMENT,
  order_id int NOT NULL,
  order_item_id int NOT NULL,
  expected_qty decimal(15,4) NOT NULL,
  counted_qty decimal(15,4) NOT NULL,
  is_mismatch tinyint(1) NOT NULL DEFAULT '0',
  verified_by varchar(20) DEFAULT NULL,
  verified_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_line (order_item_id),
  KEY idx_order (order_id),
  KEY idx_mismatch (is_mismatch),
  KEY verified_by (verified_by),
  CONSTRAINT order_verifications_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT order_verifications_ibfk_2 FOREIGN KEY (order_item_id) REFERENCES order_items (id) ON DELETE CASCADE,
  CONSTRAINT order_verifications_ibfk_3 FOREIGN KEY (verified_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- agent_commissions -- what an agent earned on one order line.
--
-- Deliberately never joined into an invoice: agent identity and commission stay
-- off the printed document (R21). The party must not see what their agent is
-- paid, so this is a separate table rather than columns on order_items, and
-- nothing in the invoice path reads it.
--
-- percent and amount are both stored. The rate can be renegotiated, and a
-- historical line must keep the rate it was actually paid at.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_commissions (
  id int NOT NULL AUTO_INCREMENT,
  agent_id int NOT NULL,
  order_id int NOT NULL,
  order_item_id int DEFAULT NULL,
  sale_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  percent decimal(5,2) NOT NULL DEFAULT '0.00',
  amount decimal(15,2) NOT NULL DEFAULT '0.00',
  status enum('pending','paid') NOT NULL DEFAULT 'pending',
  paid_at datetime DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_agent (agent_id,status),
  KEY idx_order (order_id),
  KEY order_item_id (order_item_id),
  CONSTRAINT agent_commissions_ibfk_1 FOREIGN KEY (agent_id) REFERENCES agents (id),
  CONSTRAINT agent_commissions_ibfk_2 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT agent_commissions_ibfk_3 FOREIGN KEY (order_item_id) REFERENCES order_items (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Billing
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- invoices -- raised by Gaurav, only after verification (R02).
--
-- The party's name and GSTIN are snapshotted alongside the foreign key for the
-- same reason order_items snapshots the item: a customer who later corrects
-- their trading name must not silently rewrite documents already issued.
--
-- invoice_no is UNIQUE. It is generated by the route, but the constraint is here
-- because two concurrent bills would otherwise both read the same last number.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invoices (
  id int NOT NULL AUTO_INCREMENT,
  invoice_no varchar(30) NOT NULL,
  order_id int NOT NULL,
  customer_id int NOT NULL,
  party_name varchar(100) NOT NULL,
  party_gstin varchar(20) DEFAULT NULL,
  invoice_date date NOT NULL,
  due_on date DEFAULT NULL,
  sub_total decimal(15,2) NOT NULL DEFAULT '0.00',
  gst_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  grand_total decimal(15,2) NOT NULL DEFAULT '0.00',
  amount_paid decimal(15,2) NOT NULL DEFAULT '0.00',
  settled_on date DEFAULT NULL,
  cd_percent decimal(6,4) DEFAULT NULL,
  cd_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  status enum('issued','cancelled') NOT NULL DEFAULT 'issued',
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_invoice_no (invoice_no),
  KEY idx_order (order_id),
  KEY idx_customer (customer_id),
  KEY idx_date (invoice_date),
  KEY created_by (created_by),
  KEY idx_open (customer_id,settled_on,invoice_date),
  CONSTRAINT invoices_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id),
  CONSTRAINT invoices_ibfk_2 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT invoices_ibfk_3 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- invoice_items -- the billed lines, snapshotted.
--
-- rate here may differ from order_items.rate: the rate is Gaurav's to edit at
-- billing time (R04) and this records what was actually charged. below_cost is
-- stored rather than derived because purchase cost moves, and the question the
-- flag answers is "was this knowingly billed under cost at the time".
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invoice_items (
  id int NOT NULL AUTO_INCREMENT,
  invoice_id int NOT NULL,
  item_id int NOT NULL,
  item_name varchar(100) NOT NULL,
  hsn varchar(20) DEFAULT NULL,
  qty decimal(15,4) NOT NULL,
  rate decimal(15,2) NOT NULL,
  discount decimal(5,2) DEFAULT '0.00',
  gst_percent decimal(5,2) DEFAULT '0.00',
  gst_amount decimal(15,2) DEFAULT '0.00',
  total decimal(15,2) NOT NULL,
  below_cost tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (id),
  KEY idx_invoice (invoice_id),
  KEY item_id (item_id),
  CONSTRAINT invoice_items_ibfk_1 FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE CASCADE,
  CONSTRAINT invoice_items_ibfk_2 FOREIGN KEY (item_id) REFERENCES items (masterid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Dispatch and delivery
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- dispatch_sheets -- one driver's run for one day, built by Ajit (R03).
--
-- UNIQUE on (sheet_date, driver_id): a driver has one sheet per day. Two sheets
-- would split the run and neither would show the whole load.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS dispatch_sheets (
  id int NOT NULL AUTO_INCREMENT,
  sheet_date date NOT NULL,
  driver_id varchar(20) NOT NULL,
  zone varchar(60) DEFAULT NULL,
  departure_time varchar(10) DEFAULT NULL,
  driver_signed_at datetime DEFAULT NULL,
  driver_sign_id int DEFAULT NULL,
  expected_departure time NOT NULL DEFAULT '10:30:00',
  status enum('building','released','closed') NOT NULL DEFAULT 'building',
  released_by varchar(20) DEFAULT NULL,
  released_at datetime DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_driver_day (sheet_date,driver_id),
  KEY idx_date (sheet_date),
  KEY driver_id (driver_id),
  KEY released_by (released_by),
  KEY fk_sheet_sign (driver_sign_id),
  CONSTRAINT dispatch_sheets_ibfk_1 FOREIGN KEY (driver_id) REFERENCES users (id),
  CONSTRAINT dispatch_sheets_ibfk_2 FOREIGN KEY (released_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_sheet_sign FOREIGN KEY (driver_sign_id) REFERENCES attachments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- dispatch_stops -- the orders on a sheet, in delivery order.
--
-- `seq` is the DELIVERY sequence, not the load sequence. The auto is loaded in
-- reverse -- last drop at the bottom of the pile -- but the driver reads this
-- list far more often than the loader does, so it is stored the way it is read
-- and the dispatch screen reverses it for loading.
--
-- The driver may reorder en route, so seq is a suggestion and `state` is what
-- actually happened. UNIQUE on order_id: an order rides on one sheet.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS dispatch_stops (
  id int NOT NULL AUTO_INCREMENT,
  sheet_id int NOT NULL,
  order_id int NOT NULL,
  seq int NOT NULL DEFAULT '0',
  cartons int NOT NULL DEFAULT '1',
  is_urgent tinyint(1) NOT NULL DEFAULT '0',
  state enum('pending','active','done','failed') NOT NULL DEFAULT 'pending',
  note varchar(255) DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY unique_order (order_id),
  KEY idx_sheet (sheet_id,seq),
  CONSTRAINT dispatch_stops_ibfk_1 FOREIGN KEY (sheet_id) REFERENCES dispatch_sheets (id) ON DELETE CASCADE,
  CONSTRAINT dispatch_stops_ibfk_2 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- deliveries -- proof that goods reached a person (R06).
--
-- received_by is the NAME of whoever took the goods, not a user id -- it is the
-- shop boy, and he has no account. A successful delivery is required to carry
-- one, because a delivery with nobody's name against it proves nothing.
--
-- There is deliberately no party signature column. A signature scrawled on a
-- phone proves nothing about who held it, and chasing one at a counter is what
-- made drivers skip proof entirely. photo_ref is the evidence.
--
-- A failed attempt is a real result the day must record, hence status/reason
-- rather than simply no row.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS deliveries (
  id int NOT NULL AUTO_INCREMENT,
  order_id int NOT NULL,
  status enum('delivered','undelivered') NOT NULL,
  received_by varchar(100) DEFAULT NULL,
  photo_ref varchar(255) DEFAULT NULL,
  reason varchar(60) DEFAULT NULL,
  latitude decimal(10,8) DEFAULT NULL,
  longitude decimal(11,8) DEFAULT NULL,
  delivered_by varchar(20) DEFAULT NULL,
  delivered_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_order (order_id),
  KEY idx_status (status),
  KEY delivered_by (delivered_by),
  CONSTRAINT deliveries_ibfk_1 FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
  CONSTRAINT deliveries_ibfk_2 FOREIGN KEY (delivered_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Returns and credit
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- sales_returns -- goods coming back from a party.
--
-- Accepting one writes `return` movements to stock_movements and recomputes the
-- cached quantity in the same transaction. The original sale's movements are
-- left exactly as they are: the ledger is append-only, so a return is new rows,
-- never an edit.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sales_returns (
  id int NOT NULL AUTO_INCREMENT,
  customer_id int NOT NULL,
  invoice_id int DEFAULT NULL,
  return_date date NOT NULL,
  total_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  penalty_total decimal(15,2) NOT NULL DEFAULT '0.00',
  credit_total decimal(15,2) DEFAULT NULL,
  status enum('pending','accepted','rejected') NOT NULL DEFAULT 'pending',
  reason varchar(60) DEFAULT NULL,
  photo_id int DEFAULT NULL,
  cn_due_at datetime DEFAULT NULL,
  cn_alerted_at datetime DEFAULT NULL,
  note varchar(255) DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_customer (customer_id),
  KEY idx_date (return_date),
  KEY invoice_id (invoice_id),
  KEY created_by (created_by),
  KEY idx_cn_due (cn_due_at),
  KEY fk_return_photo (photo_id),
  CONSTRAINT fk_return_photo FOREIGN KEY (photo_id) REFERENCES attachments (id) ON DELETE SET NULL,
  CONSTRAINT sales_returns_ibfk_1 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT sales_returns_ibfk_2 FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE SET NULL,
  CONSTRAINT sales_returns_ibfk_3 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- sales_return_items
-- Added by migration. See migrations/ for the reasoning behind this table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sales_return_items (
  id int NOT NULL AUTO_INCREMENT,
  return_id int NOT NULL,
  item_id int NOT NULL,
  item_name varchar(100) NOT NULL,
  sold_qty decimal(15,4) NOT NULL,
  return_qty decimal(15,4) NOT NULL,
  rate decimal(15,2) NOT NULL,
  amount decimal(15,2) NOT NULL,
  reason varchar(60) DEFAULT NULL,
  is_saleable tinyint(1) NOT NULL DEFAULT '1',
  penalty_percent decimal(6,4) DEFAULT NULL,
  penalty_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  credit_amount decimal(15,2) DEFAULT NULL,
  PRIMARY KEY (id),
  KEY idx_return (return_id),
  KEY item_id (item_id),
  CONSTRAINT sales_return_items_ibfk_1 FOREIGN KEY (return_id) REFERENCES sales_returns (id) ON DELETE CASCADE,
  CONSTRAINT sales_return_items_ibfk_2 FOREIGN KEY (item_id) REFERENCES items (masterid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Field sales
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- estimates -- a quote. Books nothing.
--
-- No stock is committed, no ledger row is written, and it never reaches the
-- approval queue. That is the whole reason it exists: quoting a builder should
-- not tie up goods someone else can sell today. Converting it creates a real
-- order, and converted_order_id records which.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS estimates (
  id int NOT NULL AUTO_INCREMENT,
  customer_id int NOT NULL,
  estimate_date date NOT NULL,
  valid_days int NOT NULL DEFAULT '15',
  valid_until date DEFAULT NULL,
  follow_up_on date DEFAULT NULL,
  attempts int NOT NULL DEFAULT '0',
  lost_reason varchar(60) DEFAULT NULL,
  closed_at datetime DEFAULT NULL,
  shared_at datetime DEFAULT NULL,
  shared_to varchar(20) DEFAULT NULL,
  shared_by varchar(20) DEFAULT NULL,
  total_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  status enum('draft','sent','converted','expired','lost') NOT NULL DEFAULT 'draft',
  converted_order_id int DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_customer (customer_id),
  KEY idx_status (status),
  KEY converted_order_id (converted_order_id),
  KEY created_by (created_by),
  KEY idx_follow_up (follow_up_on,status),
  KEY fk_estimate_sharer (shared_by),
  CONSTRAINT estimates_ibfk_1 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT estimates_ibfk_2 FOREIGN KEY (converted_order_id) REFERENCES orders (order_id) ON DELETE SET NULL,
  CONSTRAINT estimates_ibfk_3 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_estimate_sharer FOREIGN KEY (shared_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

