-- ===========================================================================
-- Cash and close
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- cheques -- collected, banked, cleared or bounced.
--
-- A bounced cheque keeps its row and its status rather than being deleted: the
-- money is not in, the party still owes it, and the history of the attempt is
-- what a payment dispute turns on.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cheques (
  id int NOT NULL AUTO_INCREMENT,
  cheque_no varchar(30) NOT NULL,
  customer_id int NOT NULL,
  bank_name varchar(120) DEFAULT NULL,
  deposit_bank varchar(60) DEFAULT NULL,
  deposit_instruction varchar(255) DEFAULT NULL,
  amount decimal(15,2) NOT NULL,
  cheque_date date NOT NULL,
  status enum('received','handed','deposited','cleared','bounced','cancelled') NOT NULL DEFAULT 'received',
  deposited_at datetime DEFAULT NULL,
  cleared_at datetime DEFAULT NULL,
  collected_by varchar(20) DEFAULT NULL,
  handed_to varchar(20) DEFAULT NULL,
  handed_at datetime DEFAULT NULL,
  deposited_by varchar(20) DEFAULT NULL,
  deposit_slip_photo_id int DEFAULT NULL,
  salesman_id varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_status (status),
  KEY idx_customer (customer_id),
  KEY collected_by (collected_by),
  KEY idx_due (cheque_date,status),
  KEY fk_cheque_handed (handed_to),
  KEY fk_cheque_depositor (deposited_by),
  KEY fk_cheque_slip (deposit_slip_photo_id),
  KEY fk_cheque_salesman (salesman_id),
  CONSTRAINT cheques_ibfk_1 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT cheques_ibfk_2 FOREIGN KEY (collected_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cheque_depositor FOREIGN KEY (deposited_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cheque_handed FOREIGN KEY (handed_to) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cheque_salesman FOREIGN KEY (salesman_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cheque_slip FOREIGN KEY (deposit_slip_photo_id) REFERENCES attachments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===========================================================================
-- Payments
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- payments -- money actually received against a party's account.
--
-- This is what customers.closing_balance was always missing. The column was
-- reported on across the app -- the approval screen's "Outstanding", the
-- register's ageing -- while nothing ever wrote it, so every figure derived
-- from it was whatever had been seeded.
--
-- closing_balance is now a CACHE of this table and invoices, in exactly the way
-- items.qty is a cache of stock_movements:
--
--   closing_balance = SUM(invoices.grand_total  WHERE status='issued')
--                   - SUM(payments.amount)
--                   - SUM(credit_notes.amount   WHERE status='issued')
--
-- maintained inside the same transaction as the row that changed it. Never
-- write it on its own; call recomputeBalance() in utils/workflow.js.
--
-- cheque_id links a cheque-mode receipt back to the instrument, so a bounce can
-- find the payment it invalidated.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payments (
  id int NOT NULL AUTO_INCREMENT,
  receipt_no varchar(30) NOT NULL,
  customer_id int NOT NULL,
  invoice_id int DEFAULT NULL,
  cheque_id int DEFAULT NULL,
  amount decimal(15,2) NOT NULL,
  mode enum('cash','cheque','upi','bank') NOT NULL DEFAULT 'cash',
  payment_date date NOT NULL,
  note varchar(255) DEFAULT NULL,
  status enum('received','reversed') NOT NULL DEFAULT 'received',
  collected_by varchar(20) DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_receipt_no (receipt_no),
