-- ---------------------------------------------------------------------------
-- credit_notes -- money owed back to a party.
--
-- `pending` means promised but not yet posted to the ledger. That distinction is
-- the point of the table: an unissued credit is an understated liability at
-- month end, and it is the only figure on the screen that can still be wrong.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS credit_notes (
  id int NOT NULL AUTO_INCREMENT,
  note_no varchar(30) NOT NULL,
  customer_id int NOT NULL,
  invoice_id int DEFAULT NULL,
  return_id int DEFAULT NULL,
  amount decimal(15,2) NOT NULL,
  reason varchar(255) DEFAULT NULL,
  origin enum('return','cash_discount','manual') NOT NULL DEFAULT 'return',
  payment_id int DEFAULT NULL,
  status enum('pending','issued','cancelled') NOT NULL DEFAULT 'pending',
  note_date date NOT NULL,
  issued_by varchar(20) DEFAULT NULL,
  issued_at datetime DEFAULT NULL,
  approved_by varchar(20) DEFAULT NULL,
  approved_at datetime DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_note_no (note_no),
  KEY idx_customer (customer_id,status),
  KEY invoice_id (invoice_id),
  KEY return_id (return_id),
  KEY issued_by (issued_by),
  KEY idx_origin (origin),
  KEY fk_cn_approver (approved_by),
  KEY fk_cn_payment (payment_id),
  CONSTRAINT credit_notes_ibfk_1 FOREIGN KEY (customer_id) REFERENCES customers (masterid),
  CONSTRAINT credit_notes_ibfk_2 FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE SET NULL,
  CONSTRAINT credit_notes_ibfk_3 FOREIGN KEY (return_id) REFERENCES sales_returns (id) ON DELETE SET NULL,
  CONSTRAINT credit_notes_ibfk_4 FOREIGN KEY (issued_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cn_approver FOREIGN KEY (approved_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_cn_payment FOREIGN KEY (payment_id) REFERENCES payments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

