-- ===========================================================================

-- ---------------------------------------------------------------------------
-- purchases -- goods received. The only thing that adds stock without an order.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS purchases (
  id int NOT NULL AUTO_INCREMENT,
  purchase_type enum('LB','LC','C','OB','OC') NOT NULL DEFAULT 'LB',
  supplier_id int DEFAULT NULL,
  supplier_name varchar(120) NOT NULL,
  invoice_no varchar(40) DEFAULT NULL,
  challan_no varchar(40) DEFAULT NULL,
  git_id int DEFAULT NULL,
  purchase_date date NOT NULL,
  sub_total decimal(15,2) NOT NULL DEFAULT '0.00',
  gst_amount decimal(15,2) NOT NULL DEFAULT '0.00',
  grand_total decimal(15,2) NOT NULL DEFAULT '0.00',
  status enum('draft','awaiting_verification','verified','posted','held') NOT NULL DEFAULT 'draft',
  doc_state enum('registered','unregistered','converted') NOT NULL DEFAULT 'registered',
  gst_due_on date DEFAULT NULL,
  gst_bill_no varchar(40) DEFAULT NULL,
  gst_received_at datetime DEFAULT NULL,
  gst_alerted_at datetime DEFAULT NULL,
  created_by varchar(20) DEFAULT NULL,
  received_by varchar(20) DEFAULT NULL,
  verified_by varchar(20) DEFAULT NULL,
  verified_at datetime DEFAULT NULL,
  rate_alert enum('none','held','proceeded') NOT NULL DEFAULT 'none',
  rate_alert_note varchar(255) DEFAULT NULL,
  approved_by varchar(20) DEFAULT NULL,
  approved_at datetime DEFAULT NULL,
  created_at datetime DEFAULT CURRENT_TIMESTAMP,
  posted_at datetime DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY unique_supplier_bill (supplier_name,purchase_type,invoice_no),
  UNIQUE KEY unique_supplier_challan (supplier_name,purchase_type,challan_no),
  KEY idx_date (purchase_date),
  KEY created_by (created_by),
  KEY idx_type_state (purchase_type,doc_state),
  KEY idx_gst_due (gst_due_on),
  KEY fk_purchase_supplier (supplier_id),
  KEY fk_purchase_git (git_id),
  KEY fk_purchase_receiver (received_by),
  KEY fk_purchase_verifier (verified_by),
  KEY fk_purchase_approver (approved_by),
  CONSTRAINT fk_purchase_approver FOREIGN KEY (approved_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_purchase_receiver FOREIGN KEY (received_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_purchase_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL,
  CONSTRAINT fk_purchase_verifier FOREIGN KEY (verified_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT purchases_ibfk_1 FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- purchase_items -- the received lines.
--
-- last_rate is the rate this item was previously bought at, copied in at entry
-- time. It is what the rate-alert screen reads, and storing it means the alert
-- survives the item master's cost being updated afterwards.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS purchase_items (
  id int NOT NULL AUTO_INCREMENT,
  purchase_id int NOT NULL,
  item_id int NOT NULL,
  item_name varchar(100) NOT NULL,
  bill_qty decimal(15,4) NOT NULL DEFAULT '0.0000',
  qty decimal(15,4) NOT NULL,
  goods_condition enum('ok','damaged','short','excess') NOT NULL DEFAULT 'ok',
  condition_note varchar(160) DEFAULT NULL,
  rate decimal(15,2) NOT NULL,
  last_rate decimal(15,2) DEFAULT NULL,
  rate_changed tinyint(1) NOT NULL DEFAULT '0',
  gst_percent decimal(5,2) DEFAULT '0.00',
  total decimal(15,2) NOT NULL,
  PRIMARY KEY (id),
  KEY idx_purchase (purchase_id),
  KEY idx_item (item_id,id),
  CONSTRAINT purchase_items_ibfk_1 FOREIGN KEY (purchase_id) REFERENCES purchases (id) ON DELETE CASCADE,
  CONSTRAINT purchase_items_ibfk_2 FOREIGN KEY (item_id) REFERENCES items (masterid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

