-- ---------------------------------------------------------------------------
-- Foreign keys that close a cycle.
--
-- `purchases` and `git_entries` reference each other deliberately: a bilty is
-- recorded days before the purchase exists (requirements 5.2), and the purchase
-- then points back at the bilty it arrived on. Neither table can be created
-- with both constraints in place, so the one that closes the loop is added
-- here, after both exist.
--
-- Added rather than skipped with FOREIGN_KEY_CHECKS = 0, which would also have
-- silently accepted a genuinely malformed constraint.
-- ---------------------------------------------------------------------------
ALTER TABLE purchases
  ADD CONSTRAINT fk_purchase_git FOREIGN KEY (git_id)
  REFERENCES git_entries (id) ON DELETE SET NULL ON UPDATE NO ACTION;

-- ---------------------------------------------------------------------------
-- Reference rows.
--
-- The one exception to "structure only". These are vocabulary the code reads
-- by key and cannot work without: the two shift timings that decide whether a
-- check-in was late, and the cash-discount ladder that decides what an early
-- payment earns. A database without them is broken, not empty.
--
-- They are rows rather than constants because management adjusts them — the
-- grace period and the half-day cut-off are business decisions, and changing
-- one should not need a deployment.
-- ---------------------------------------------------------------------------
INSERT INTO shifts (code, name, starts_at, grace_until, ends_at, half_day_before, absent_after_minutes, is_active) VALUES
  ('A', 'Shift A', '10:00:00', '10:10:00', '18:45:00', '18:00:00', 60, 1),
  ('B', 'Shift B', '11:00:00', '11:10:00', '20:00:00', '19:00:00', 60, 1)
ON DUPLICATE KEY UPDATE name = VALUES(name), starts_at = VALUES(starts_at), grace_until = VALUES(grace_until), ends_at = VALUES(ends_at), half_day_before = VALUES(half_day_before), absent_after_minutes = VALUES(absent_after_minutes), is_active = VALUES(is_active);

INSERT INTO cash_discount_bands (id, label, min_days, max_days, percent, is_active) VALUES
  (1, '0 to 2 days', 0, 2, '0.0250', 1),
  (2, '3 to 10 days', 3, 10, '0.0200', 1),
  (3, '11 to 20 days', 11, 20, '0.0100', 1)
ON DUPLICATE KEY UPDATE label = VALUES(label), min_days = VALUES(min_days), max_days = VALUES(max_days), percent = VALUES(percent), is_active = VALUES(is_active);
